css:
:root{color-scheme:dark;--ink:#f3e9d2;--muted:#b3a383;--gold:#e0b04a;--line:#ffffff17;--panel:#16110b}
*{box-sizing:border-box}
button,a{-webkit-tap-highlight-color:transparent}
button{font:inherit;color:inherit;cursor:pointer;border:0;background:none}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--gold);outline-offset:4px}
button:disabled{opacity:.35;cursor:not-allowed}
button:hover:not(:disabled){filter:brightness(1.15)}
a{color:#f6d98f}
.eyebrow{font-size:10px;letter-spacing:2px;color:#c2ad84;font-weight:600;line-height:1.8;margin:0;font-family:"Courier New",Courier,monospace}
#celebration{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5}
.coin{position:absolute;animation:fall 2.4s ease-in both}
dialog{border:1px solid #8a642066;background:linear-gradient(#1b140c,#120d08);color:#f3e9d2;border-radius:10px;width:min(760px,94vw);max-height:86vh;padding:24px 28px;box-shadow:0 35px 120px #000c}
dialog::backdrop{background:#060402d0;backdrop-filter:blur(8px)}
.modal-head{display:flex;align-items:center;justify-content:space-between}
.modal-head button{font-size:30px;color:#c2ad84;min-width:44px;min-height:44px}
dialog h2{font:34px Georgia,serif;color:#f6d98f;margin:12px 0;font-weight:400}
dialog p,dialog li{font-size:13px;color:#d4c6a8;line-height:1.75}
dialog h3{font:700 12px "Courier New",Courier,monospace;letter-spacing:1.5px;color:#f6d98f;margin-top:26px}
dialog code{color:#f6d98f;font-size:12px}
.cta{background:linear-gradient(#f6d98f,#e0b04a 55%,#a57a26);color:#1c1408;padding:13px 20px;border-radius:5px;font-weight:700;font-size:12px;letter-spacing:1px;margin:12px 8px 0 0;display:inline-flex;align-items:center;min-height:44px;text-decoration:none;font-family:"Courier New",Courier,monospace}
.outline{border:1px solid #8a642099;padding:12px 18px;border-radius:5px;font-size:12px;margin:8px 8px 0 0;display:inline-flex;align-items:center;min-height:44px}
.paytable{width:100%;border-collapse:collapse;font-size:12px}
.paytable th{color:#b3a383;font-weight:400;font-size:10px;text-align:left;letter-spacing:1px}
.paytable td,.paytable th{padding:9px;border-bottom:1px solid #ffffff12;vertical-align:middle}
.pay-icon{width:34px;height:34px;vertical-align:middle;margin-right:8px}
.pay-icon.credit{width:64px;height:64px;display:inline-block;margin:8px 8px 0 0;border-radius:4px}
.rule-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.line-card{border:1px solid #ffffff14;padding:8px;text-align:center;font-size:10px;color:#b3a383;border-radius:4px}
.line-card svg{width:100%;height:32px}
.stat-cards{display:flex;gap:10px;margin:18px 0}
.stat-cards>div{padding:14px;border:1px solid #ffffff16;border-radius:6px;flex:1;background:#0d0a06}
.stat-cards span{display:block;font-size:11px;color:#b3a383}
.stat-cards strong{display:block;font-size:22px;margin-top:8px;font-weight:400;color:#f6d98f;font-family:"Courier New",Courier,monospace}
.setting{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:12px 0;border-bottom:1px solid #ffffff15;font-size:13px;min-height:44px}
.setting input[type=range]{width:45%;accent-color:#e0b04a}
.setting input[type=checkbox]{accent-color:#e0b04a;width:22px;height:22px}
.history-wrap{max-height:330px;overflow:auto}
.labtag{background:#e0b04a;color:#1c1408;padding:1px 5px;border-radius:3px;font-size:10px}
.fine{font-size:11px!important;color:#a8987a!important}
.hash{font:12px/1.6 ui-monospace,Menlo,Consolas,monospace;word-break:break-all;color:#f3e9d2;background:#0d0a06;border:1px solid #ffffff14;border-radius:6px;padding:12px;white-space:pre-wrap}
ul.posts{padding-left:18px}ul.posts li{margin:4px 0}
.error-panel{max-width:520px;padding:0 24px;text-align:center;line-height:1.7}
.error-panel h2{font-weight:400;font-size:24px;color:#f6d98f;margin:0 0 10px}
.error-panel p{font-size:13px;color:#d4c6a8;margin:6px 0}
.noscript{position:fixed;inset:0;z-index:60;margin:0;display:flex;align-items:center;justify-content:center;background:#0c0a08;color:#eee}
@keyframes rotate{to{transform:rotate(360deg)}}
@keyframes pulse{50%{box-shadow:0 0 14px #e0b04a66}}
@keyframes fall{0%{transform:translateY(-30px) rotate(0);opacity:0}10%{opacity:1}100%{transform:translateY(100vh) rotate(540deg);opacity:0}}
.coin.inf{font-size:26px;color:#f6d98f;text-shadow:0 0 12px #e0b04a}
/* Bonus Lab */
.lab-list{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin:12px 0}
.lab-item{display:flex;gap:10px;align-items:center;border:1px solid #8a642055;border-radius:6px;padding:8px 10px;min-height:52px;cursor:pointer;background:#0d0a06}
.lab-item input{accent-color:#e0b04a;width:20px;height:20px;flex:0 0 auto}.lab-item b{display:block;font-size:13px;color:#f6d98f}.lab-item small{display:block;font-size:11px;color:#a8987a}
.lab-item:has(input:checked){border-color:#e0b04a;background:#2a1f10}
.lab-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:8px 0;font-size:12px;color:#d4c6a8}
.lab-row select,.lab-row input[type=number]{background:#0d0a06;color:#f3e9d2;border:1px solid #8a642099;border-radius:5px;min-height:44px;padding:0 8px;font:inherit;margin-left:6px}
.lab-row input[type=number]{width:110px}.lab-row .chk{display:flex;gap:6px;align-items:center;min-height:44px}.lab-row .chk input{width:20px;height:20px;accent-color:#e0b04a}
.test-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.test-grid button{border:1px solid #8a642088;border-radius:6px;padding:12px 8px;color:#f3e9d2;font-size:12px;min-height:44px}

:root{--acc:#e0b04a;--acc2:#f6d98f;--bg:#0c0a08;--barh:150px;--safe-b:env(safe-area-inset-bottom,0px);--safe-l:env(safe-area-inset-left,0px);--safe-r:env(safe-area-inset-right,0px)}
html,body{margin:0;height:100%;overflow:hidden;background:var(--bg)}
body{display:flex;flex-direction:column;color:var(--ink);font-family:Georgia,"Times New Roman",serif;-webkit-user-select:none;user-select:none}
#stage{position:relative;flex:1 1 auto;min-height:0;display:flex;flex-direction:column;align-items:stretch;justify-content:center;background:radial-gradient(ellipse at 50% 35%,#21180e,#0c0a08 70%);touch-action:manipulation}
#view{width:100%;flex:1 1 auto;min-height:0;height:0;object-fit:contain;display:block;touch-action:manipulation}
#statusLine{position:static;margin:0;flex:0 0 auto;text-align:center;padding:4px 12px 6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:11px "Courier New",Courier,monospace;letter-spacing:1.4px;color:var(--acc2);pointer-events:none;text-shadow:0 0 8px #000;padding:0 12px}
.side-meters{position:absolute;top:8px;left:calc(8px + var(--safe-l));font:10px "Courier New",Courier,monospace;letter-spacing:1.2px;color:#b3a383;display:flex;gap:14px;pointer-events:none;flex-wrap:wrap}.side-meters b{color:var(--acc2);font-weight:400;font-variant-numeric:tabular-nums}
#fsbar{flex:0 0 auto;background:linear-gradient(#2a1a0e,#1a110a);border-top:2px solid #8a6420;padding:8px calc(10px + var(--safe-r)) calc(8px + var(--safe-b)) calc(10px + var(--safe-l));display:flex;flex-direction:column;gap:8px;z-index:3;box-shadow:0 -10px 30px #0008}
#featureBar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;background:#f1e6c8;color:#211a12;border:1px solid #8a6420;border-radius:6px;padding:8px 12px}
#featureBar .eyebrow{color:#7a5d2e}
#featureBar[hidden]{display:none}.fb-head{display:flex;flex-direction:column;gap:2px;min-width:150px;flex:0 1 240px}.fb-head strong{font:700 18px "Courier New",Courier,monospace;color:#211a12}.fb-head span:last-child{font-size:12px;color:#4a3a22;line-height:1.35}
#fbBody{display:flex;gap:6px;align-items:center;flex-wrap:wrap;flex:1 1 auto;justify-content:flex-end}
.pick{width:44px;height:44px;border:1px solid #6b4a22;border-radius:5px;color:#211a12;background:linear-gradient(#d9b67c,#b48a52);font-size:14px;font-weight:700}.pick.picked{background:#b8261d;color:#fff4e6;border-color:#7a1810}
.bar-cta{min-height:44px;background:linear-gradient(#f6d98f,#e0b04a 55%,#a57a26);color:#1c1408;padding:0 18px;border-radius:5px;font:700 13px "Courier New",Courier,monospace;letter-spacing:1px;box-shadow:0 3px 0 #5e4314}.bar-cta.ghost{background:none;color:#4a3a22;border:1px solid #8a6420;box-shadow:none}
.row{display:flex;gap:8px;align-items:stretch}
.row.main{align-items:center}.row.menu{overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;-webkit-overflow-scrolling:touch}.row.menu::-webkit-scrollbar{display:none}
.read{display:flex;flex-direction:column;justify-content:center;min-width:0;padding:0 10px;border-left:1px solid var(--line)}.read:first-child{border-left:0;padding-left:2px}
.read label{font:9px "Courier New",Courier,monospace;letter-spacing:1.3px;color:#c2ad84;margin:0 0 3px;white-space:nowrap}.read strong{font:400 22px "Courier New",Courier,monospace;letter-spacing:-.5px;font-variant-numeric:tabular-nums;white-space:nowrap}.read small{font:9px "Courier New",Courier,monospace;letter-spacing:1px;color:#b3a383}
.read.win strong{color:var(--acc2)}
.stepper{display:flex;align-items:center;gap:6px}.stepper strong{font-size:20px;min-width:44px;text-align:center}.stepper button{border:1px solid #8a6420;border-radius:50%;width:44px;height:44px;color:#f6d98f;font-size:20px;background:radial-gradient(#2f2418,#140e08)}
.deck{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:68px;min-height:44px;padding:4px 8px;border:1px solid #8a642077;border-radius:5px;background:linear-gradient(#24190f,#150e08);flex:0 0 auto}.deck b{font:700 10px "Courier New",Courier,monospace;letter-spacing:1px;color:#f6d98f;white-space:nowrap}.deck i{font-style:normal;font-size:9px;color:#b3a383;white-space:nowrap}
.deck.vol{padding:0 8px}.deck.vol b{margin-top:2px}.deck.vol input{width:96px;height:44px;accent-color:#e0b04a;margin:-10px 0 -8px}
.deck[aria-pressed=true]{border-color:var(--acc);background:#3a2a12}.deck[aria-pressed=true] b{color:#fff3d0}
.deck.hot{border-color:var(--acc2);background:#3a2a12;animation:pulse 1.4s ease-in-out infinite}.deck[hidden]{display:none}
.spin{margin-left:auto;background:radial-gradient(circle at 40% 30%,#f9e3a6,#e0b04a 45%,#8a6420);color:#1c1408;min-width:160px;min-height:56px;padding:4px 18px;border-radius:30px;box-shadow:0 4px 0 #4a3410,0 0 30px #e0b04a33;display:flex;flex-direction:column;align-items:center;justify-content:center;flex:0 0 auto;position:relative;border:2px solid #f6d98f}
.spin #spinText{font:700 15px "Courier New",Courier,monospace;letter-spacing:2px}.spin small{font-size:9px;letter-spacing:1px;opacity:.8;margin:0}.spin .spin-icon{position:absolute;right:14px;top:4px;font-size:18px}.spin:active{transform:translateY(3px);box-shadow:0 1px 0 #4a3410}.spin.spinning .spin-icon{animation:rotate .7s linear infinite}.spin.small #spinText{font-size:12px;letter-spacing:1px}
#fsExit{border-color:#e0b04a}body:not(.fs-on) #fsExit{display:none}body.fs-on #fsBtn{display:none}
body.lab-on #fsbar{border-top-color:#e0b04a;box-shadow:0 -4px 0 #e0b04a inset}
#toast{position:fixed;bottom:calc(var(--barh) + 12px);left:50%;transform:translate(-50%,15px);opacity:0;background:#f1e6c8;color:#211a12;border-radius:4px;padding:11px 18px;font:13px "Courier New",Courier,monospace;pointer-events:none;transition:.2s;z-index:12;max-width:90vw;text-align:center;border:1px solid #8a6420}#toast.show{opacity:1;transform:translate(-50%,0)}
dialog{z-index:20}
#loading{position:fixed;inset:0;background:var(--bg);z-index:50;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .5s;color:var(--acc2)}#loading b{font:40px Georgia,serif;font-weight:400;letter-spacing:4px;color:var(--acc)}#loading p{font:11px "Courier New",Courier,monospace;letter-spacing:3px;margin-top:24px}#loading small{font-size:11px;color:#b3a383}
@media(max-width:760px){#statusLine .src{display:none}.read strong{font-size:18px}.read{padding:0 6px}.spin{min-width:120px;padding:4px 10px}.fb-head{flex:1 1 100%}#fbBody{justify-content:flex-start}.row.main{flex-wrap:wrap}.row.main .spin{flex:1}.deck{min-width:62px}.stepper strong{min-width:34px;font-size:18px}dialog{padding:16px}.rule-grid{grid-template-columns:repeat(4,1fr)}.lab-list{grid-template-columns:1fr}.side-meters{display:none}}
@media(max-height:520px){#fsbar{gap:5px;padding-top:5px}.read strong{font-size:17px}.fb-head strong{font-size:15px}.fb-head span:last-child{display:none}.fb-head{min-width:110px;flex:0 1 150px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
